<?php namespace App\Http\Controllers;use App\Models\{Product,Order};use Illuminate\Http\Request;class ApiController extends Controller{public function products(Request $r){return Product::with(['category','reviews'])->where('status',true)->when($r->search,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like','%'.$s.'%')->orWhere('description','like','%'.$s.'%')))->when($r->category,fn($q,$c)=>$q->where('category_id',$c))->paginate(min((int)$r->input('per_page',20),100));}public function product(Product $product){return $product->load(['category','reviews','variants','images']);}public function orders(Request $r){return $r->user()->orders()->with('items')->latest()->paginate(20);}public function order(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,403);return $order->load('items');}}
